INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'Physics', 'Unit 2', 'Molarum Grade 10 — Physics Uniformly Accelerated Motion', 'Source-grounded Molarum Grade 10 Physics questions for Uniformly Accelerated Motion.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('52d8796a-fcc5-4dae-8cc2-82f5d4ba43d2'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car starts from rest and accelerates uniformly at 2 m/s^2 for 5 s. What is the displacement during this interval?', 'a) 25 m', 'Using s = ut + (1/2) a t^2 with u = 0, a = 2 m/s^2, t = 5 s: s = 0 + 0.5 × 2 × 25 = 25 m.', 0),('248e2693-39b9-4417-8bdd-ac522767fc99'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'Displacement is best described as:', 'b) final position minus initial position', 'Displacement is a vector describing the straight-line change in position from the initial to the final point, not the path length.', 1),('5e924c6b-e578-46a4-889b-6776254789a3'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A particle’s position is given by s = 2t^2 + 3 (m). What is the average velocity from t = 0 to t = 5 s?', 'b) 10 m/s', 's(5) = 2(25) + 3 = 53 m; s(0) = 3 m; Δs = 50 m; Δt = 5 s; v_avg = Δs/Δt = 50/5 = 10 m/s.', 2),('02227cbd-e777-40c0-8614-df142124ddc1'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'On a velocity-time graph that rises linearly from 0 to 20 m/s over 4 s, what is the acceleration?', 'a) 5 m/s^2', 'Acceleration is the slope of the v–t graph: a = Δv/Δt = (20 − 0)/4 = 5 m/s^2.', 3),('d1ca17b8-0874-49de-8972-78dc344ee5b4'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car starts from a speed of 4 m/s and accelerates at 3 m/s^2 for 6 s. It then continues at a constant speed for 4 s. What is the total displacement in 10 s?', 'b) 166 m', 'Phase 1: s1 = ut + 0.5at^2 = 4(6) + 0.5(3)(36) = 78 m; v1 = u + at = 4 + 18 = 22 m/s; Phase 2: s2 = v1×4 = 88 m; total = 78 + 88 = 166 m.', 4),('33a250a3-314d-4859-8dc4-02290ce79a7d'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'true_false', 'The instantaneous velocity is the slope of the position-time graph.', 'True', 'The instantaneous velocity at a specific time is given by the slope of the position-time graph at that time.', 5),('232aab66-120b-46f2-8050-bec01f44f397'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Define acceleration.', 'Acceleration is the rate of change of velocity with respect to time.', 'Acceleration describes how velocity changes per unit time (a = Δv/Δt).', 6),('2e8ad3b2-8df5-4a2c-8d87-df48e43bfcb1'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'What does the slope of a velocity-time graph represent?', 'Acceleration.', 'The slope of the velocity-time graph corresponds to the acceleration (for constant acceleration).', 7),('9ea5bc05-6567-4e8c-859e-13b6f127193e'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A car starts from rest and accelerates at 3 m/s^2 for 5 s, then decelerates at -2 m/s^2 for 4 s. What is the final velocity after the 9 s, and the total displacement during those 9 s? Provide the numerical values with units.', 'Final velocity: 7 m/s; Total displacement: 81.5 m', 'Phase 1: v1 = 0 + 3(5) = 15 m/s; s1 = 0.5(3)(25) = 37.5 m. Phase 2: v2 = 15 + (-2)(4) = 7 m/s; s2 = v1(4) + 0.5(-2)(4^2) = 15(4) + 0.5(-2)(16) = 60 - 16 = 44 m. Total displacement = 37.5 + 44 = 81.5 m.', 8),('0c43a4ba-c227-473d-864b-a7d0d7703c0a'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A particle starts with velocity 12 m/s and accelerates uniformly at 0.5 m/s^2 for 10 s. What is the displacement during the 10 s? Provide the numerical answer with units and brief method.', '145 m', 'Using s = ut + (1/2) a t^2 with u = 12 m/s, a = 0.5 m/s^2, t = 10 s: s = 12(10) + 0.5(0.5)(100) = 120 + 25 = 145 m.', 9),('64d8a0e4-c764-42de-811b-6b47d26983f4'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car increases its velocity from 0 to 20 m/s in 4 s. What is its average acceleration?', '5 m/s^2', 'Average acceleration a_avg = Δv/Δt = (20 − 0)/4 = 5 m/s^2.', 10),('8350707e-6e5f-49ba-8d1b-9760bab8dc41'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A ball starts from rest and accelerates at 2 m/s^2 for 3 s. How far does it travel in that time?', '9 m', 's = ut + 0.5 a t^2 = 0 + 0.5*2*(3)^2 = 9 m.', 11),('6f3cc5c6-8a1d-439a-8248-3a326efffe9f'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'In a velocity-time graph for an object with constant acceleration, what does the slope represent?', 'Acceleration', 'For constant acceleration, a is the slope of v vs t.', 12),('09e305d5-5cfd-4546-84ae-d99f5e5f18a7'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car starts at 5 m/s and accelerates at 1 m/s^2 for 6 s. Its final velocity is', '11 m/s', 'v = u + a t = 5 + 1*6 = 11 m/s.', 13),('090f1246-4b5b-4fbb-8a01-985182b33969'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'An object with initial speed u = 4 m/s accelerates at a = 2 m/s^2. It covers a displacement of s = 80 m in a straight line. What is the time t required? Use s = ut + 0.5 a t^2.', '7.2 s', 'Solve 80 = 4 t + 1 t^2 → t^2 + 4 t − 80 = 0; t = [-4 + sqrt(16+320)]/2 ≈ 7.17 s ≈ 7.2 s.', 14),('165a9f38-5d9d-4ed8-8f2d-ade2499345a1'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'true_false', 'If velocity changes uniformly with time, acceleration is constant.', 'True', 'Uniform rate of velocity change implies constant acceleration.', 15),('d077f085-c59c-44d8-8b12-1554f54b8d1d'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Explain the difference between average velocity and instantaneous velocity.', 'Average velocity is displacement divided by the time interval; instantaneous velocity is the velocity at a specific instant (the limit as the time interval approaches zero).', 'Average velocity uses a finite time interval; instantaneous velocity is the velocity at a single moment.', 16),('f63c26a8-5a6c-4ada-8be9-df1e1c67f12d'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Describe how the displacement relates to the area under a velocity-time graph for motion with changing velocity.', 'Displacement equals the area under the velocity-time graph; positive area corresponds to forward motion, negative area to backward motion.', 'Area under v-t graph represents net displacement during the time interval.', 17),('bec85944-3427-4340-87d3-4e3823a7d321'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A car starts from rest (u = 0) and accelerates at a = 1.5 m/s^2 for t = 8 s. What distance does it cover? Provide all values, units, method, final unit.', '48 m', 's = ut + 0.5 a t^2 = 0 + 0.5(1.5)(8)^2 = 0.75*64 = 48 m.', 18),('ef1ec6d6-72d5-4233-8931-1aec4360225e'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'An object with initial velocity u = 4 m/s accelerates at a = 2 m/s^2. It covers a displacement s = 80 m in a straight line. Find the time t required.', '7.17 s', 'Solve 80 = 4 t + 0.5(2) t^2 → t^2 + 4 t − 80 = 0; t = [-4 + sqrt(16 + 320)]/2 ≈ 7.17 s.', 19),('201a6c3d-ba41-4f70-882f-a3110fff4b2e'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car starts from rest and accelerates uniformly at 3 m/s^2 for 4 s. What is its final velocity?', '12 m/s', 'Using v = u + at with u = 0, a = 3 m/s^2, t = 4 s; v = 0 + 3×4 = 12 m/s.', 20),('4b2dd612-984a-41b5-888b-8f3d6615f5c2'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'Which of the following statements about constant acceleration is true?', 'The velocity changes at a constant rate', 'Constant acceleration means the rate of change of velocity is constant; velocity changes at a constant rate.', 21),('80b40cb0-8119-43b0-873c-7bcace203f14'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'true_false', 'The velocity–time graph of an object with constant acceleration is a straight line.', 'True', 'With constant acceleration, velocity changes linearly with time, producing a straight-line v-t graph.', 22),('048e4a16-6366-47d2-8c88-bfa55275b79e'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'Which equation gives the displacement s after time t for an object with initial velocity u and constant acceleration a?', 's = ut + 1/2 a t^2', 'For constant acceleration, displacement s = ut + (1/2) a t^2 is the standard equation.', 23),('a791b3e7-7863-42ca-8ea8-0068e3475635'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'An object starts from speed u = -5 m/s and accelerates at a = 3 m/s^2 for t = 4 s. What is the displacement s during this interval?', '4 m', 's = ut + 1/2 at^2 = (-5)(4) + 0.5(3)(16) = -20 + 24 = 4 m.', 24),('79ca75ba-1ca3-4f1e-89b0-f64e7fd9765a'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Define average velocity and instantaneous velocity, and explain how they differ.', 'Average velocity is total displacement divided by total time; instantaneous velocity is the velocity at a specific time, equal to the slope of the position-time graph at that time.', 'Average velocity uses overall displacement/time; instantaneous velocity uses the slope at a specific moment on a position-time graph.', 25),('54c61b60-0d13-40b4-8dcb-ee758e7417d4'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A particle starts from u = 10 m/s and accelerates uniformly at a = -2 m/s^2 for t = 6 s. Find the displacement s in this interval. Provide your answer with units.', '24 m', 'Using s = ut + 1/2 a t^2 = 10(6) + 0.5(-2)(6^2) = 60 - 36 = 24 m.', 26),('1c3aacb6-6bc3-4ad6-806c-da54f5643f14'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A car moves east with initial speed u = 15 m/s and experiences a constant westward acceleration a = -3 m/s^2 for t = 6 s. What is the displacement s during this interval? Provide your answer with units.', '36 m (east)', 's = ut + 1/2 a t^2 = (15)(6) + 0.5(-3)(6^2) = 90 - 54 = 36 m towards east.', 27),('67f5d7d5-5241-405a-8240-d855e64061e9'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Explain how instantaneous velocity is determined from a position-time graph and how it relates to average velocity.', 'Instantaneous velocity is the slope of the position-time graph at a single time; average velocity is the total displacement divided by the total time.', 'The slope at a single time gives instantaneous velocity; average velocity uses whole interval.', 28),('03e3b453-d533-47de-81c2-ff40c77e161a'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'The displacement–time graph for an object undergoing uniform acceleration is which of the following, and what does the slope represent?', 'A parabola; slope represents velocity', 'The displacement-time (s-t) graph for uniform acceleration is a parabola; the slope at any time is the instantaneous velocity.', 29),('9161b0a1-fdc1-420e-85ed-f8fb4f972f84'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'In one dimension, displacement is:', 'A) the distance travelled along the path', 'Displacement is the vector from the initial to the final position, including direction; it equals the change in position x2−x1 along the straight line joining the points.', 30),('85d49897-0797-4d63-8519-4ae712dd88cb'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'A car speeds up from v = 0 to v = 20 m/s in 4 seconds with constant acceleration. What is the acceleration?', 'A) 2.5 m/s^2', 'Acceleration a = Δv/Δt = (20 − 0) / 4 = 5 m/s^2.', 31),('5baa7f24-6b9a-4e6c-8970-2f7d2a4b2b55'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'Which equation would you use to relate displacement s, initial velocity u, acceleration a, and time t to find velocity after time t?', 'A) v = u + a t', 'In constant acceleration, velocity after time t is v = u + a t.', 32),('e452edd7-9421-474e-8064-e8b2d5f2c294'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'On a velocity-time graph for uniformly accelerated motion, the area under the curve between t1 and t2 represents:', 'A) time interval', 'The area under a velocity-time graph over a time interval equals the displacement during that interval.', 33),('c5581651-7429-4b34-8cc9-07bc63d3e0d3'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'multiple_choice', 'Two trains move in the same direction with speeds 20 m/s and 15 m/s. The relative speed of the second with respect to the first is:', 'A) 5 m/s', 'Relative speed is the difference of speeds when moving in the same direction: 20 − 15 = 5 m/s.', 34),('d9e5a8fd-8bab-465f-8879-c2446ecaf058'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'true_false', 'The equation s = u t + 1/2 a t^2 is valid for any motion.', 'False', 'That equation is valid only for motion with constant acceleration.', 35),('591fcd83-2b4d-4a5f-83dd-d04891ffc4e8'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Explain what instantaneous velocity means and how it differs from average velocity.', 'Instantaneous velocity is the velocity at a specific instant in time (the slope of the position-time curve at that instant). It can differ from the average velocity, which is the total displacement over a time interval divided by the length of that interval. In uniformly accelerated motion, instantaneous velocity changes with time, while average velocity over an interval equals the average of the initial and final velocities over that interval.', 'Instantaneous velocity = v(t0); average velocity over [t1,t2] = (v1 + v2)/2 for constant acceleration.', 36),('00beb23f-09c2-419b-8838-8afd958634b1'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'Describe how the slope and the area on a velocity-time graph relate to acceleration and displacement in uniformly accelerated motion.', 'The slope of the velocity-time graph gives acceleration; the area under the velocity-time graph over a time interval gives displacement.', 'For v(t) = u + at, slope = a; area under v(t) from t1 to t2 = ∫ v dt = displacement.', 37),('f494dee3-984e-4622-8959-a75757558de5'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A cart starts with velocity 5 m/s and accelerates at 2 m/s^2 for 4 s. Find its final velocity and displacement.', 'v = 13 m/s; s = 36 m', 'Final velocity: v = u + a t = 5 + 2×4 = 13 m/s. Displacement: s = ut + 1/2 a t^2 = 5×4 + 1/2×2×16 = 20 + 16 = 36 m.', 38),('f3ab8dd4-03f2-406d-84dc-4ac3d1d56870'::uuid, 'db679d51-a77e-4c6f-8334-5c84fbc88ad3'::uuid, 'fill_blank', 'A car accelerates at 2 m/s^2 for 5 s, then coasts (a = 0) for 3 s. Find the total displacement in the first 8 s.', '55 m', 'First 5 s: s1 = ut + 1/2 a t^2 = 0 + 1/2×2×25 = 25 m; velocity after 5 s: v1 = 0 + 2×5 = 10 m/s. Next 3 s: s2 = v1 × 3 = 10 × 3 = 30 m. Total s = 25 + 30 = 55 m.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
